import {ArenaScene} from './scene.js';
import {ELEMENTS,SPELLS,ENEMIES,RELICS,getSpell,recognizeGesture} from './spells.js';
const $=id=>document.getElementById(id),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
let scene;try{scene=new ArenaScene($('scene'));}catch(e){$('scene').innerHTML='<div class="error-notice">无法启动 3D 竞技场。请在支持 WebGL 的浏览器中打开，并开启硬件加速。<br><button class="gold-button" onclick="location.reload()">重新加载</button></div>';console.error(e);}
const freshPlayer=()=>({hp:100,maxHp:100,mana:100,maxMana:100,shield:0,power:1,regen:8,costMult:1,reflect:1,counterHeal:0,counterWindow:.48,charge:0,chargeRate:1,dodgeMax:3.4,dodgeDuration:.7,startShield:0});
let p=freshPlayer(),e={},runes=[],mode='campaign',phase='ready',round=0,score=0,chain=0,best=0,castCd=0,dodgeCd=0,dodgeTime=0,counterCd=0,wardTime=0,enemyTimer=2,attackIndex=0,enemyCast=null,attacks=[],playerX=0,enemyX=0,elapsed=0,announceTime=0,enemyBurn=0,enemyFreeze=0,enemySlow=0,burnTick=0,totalCounters=0,totalSpells=0,selectedRelics=[],resumePhase=null,sound=false,ctx=null,wasHidden=false,runId=0;
try{best=Number(localStorage.getItem('runeweaver.best'))||0;}catch{}$('best-score').textContent=best.toLocaleString();
function tone(freq=440,duration=.12,type='sine',volume=.08){if(!sound)return;try{ctx??=new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.5,ctx.currentTime+duration);g.gain.setValueAtTime(volume,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration);}catch{}}
function log(text,color){const div=document.createElement('div');div.className='log-entry';div.textContent=text;if(color)div.style.color=color;$('battle-log').appendChild(div);while($('battle-log').children.length>3)$('battle-log').firstChild.remove();}
function announce(title,sub='',duration=2){$('announcement').innerHTML=`${title}${sub?`<small>${sub}</small>`:''}`;announceTime=duration;$('announcement').classList.remove('pop');void $('announcement').offsetWidth;$('announcement').classList.add('pop');}
function floatDamage(n,enemy=true,label=''){const pos=scene?.projectPosition(enemy?enemyX:playerX,2.6,enemy?-4.2:4.2)||{x:innerWidth*.5,y:200};const div=document.createElement('div');div.className='floating-damage';div.textContent=label||`−${Math.round(n)}`;div.style.left=pos.x+'px';div.style.top=pos.y+'px';div.style.color=enemy?'#e9ccac':'#e99d9f';$('arena').append(div);setTimeout(()=>div.remove(),1100);}
function active(){return phase==='battle';}
function addRune(element){if(!ELEMENTS[element]||!['ready','battle'].includes(phase)||$('modal').open)return false;if(runes.length===3){log('符文槽已满 · 释放法术或按退格撤销');tone(160,.08);return false;}runes.push(element);tone(240+Object.keys(ELEMENTS).indexOf(element)*80,.12,'sine',.045);renderRunes();return true;}
function renderRunes(){const slots=$('rune-slots').querySelectorAll('div');slots.forEach((slot,i)=>{const el=ELEMENTS[runes[i]];slot.classList.toggle('filled',!!el);slot.style.setProperty('--rune-color',el?.color||'#53607a');slot.innerHTML=`<span>${el?.glyph||['Ⅰ','Ⅱ','Ⅲ'][i]}</span>`;});const spell=getSpell(runes);$('spell-preview').textContent=spell?spell.name:'选择符文，编织你的法术';$('spell-preview').style.color=spell?ELEMENTS[spell.element].color:'';$('spell-cost').textContent=spell?`${Math.ceil(spell.cost*p.costMult)} 魔力 · ${spell.damage?'基础伤害 '+spell.damage:'守护法术'}`:'最多组合 3 枚符文';}
function seedEnemy(){const base=ENEMIES[round%ENEMIES.length],scale=1+Math.floor(round/ENEMIES.length)*.3;e={...base,maxHp:Math.round(base.hp*scale),hp:Math.round(base.hp*scale),shield:base.shield||0,damage:Math.round(base.damage*scale),enraged:false};enemyCast=null;enemyTimer=2.3;enemyBurn=enemyFreeze=enemySlow=burnTick=0;attackIndex=0;enemyX=0;attacks=[];scene?.clearProjectiles();scene?.setEnemy(base.color);$('enemy-name').textContent=e.name;$('enemy-rank').textContent=`第 ${['I','II','III','IV','V','VI'][round%6]} 阶 · ${e.school}`;$('world-label').querySelector('small').textContent=e.name;document.querySelector('.enemy-portrait').textContent=e.glyph;$('round-label').textContent=`第 ${String(round+1).padStart(2,'0')} 场 · ${mode==='endless'?'无尽试炼':'六重试炼'}`;$('trial-progress').innerHTML=Array.from({length:6},(_,i)=>`<span class="trial-node ${i<round%6?'done':i===round%6?'current':''}"></span>`).join('');setIntent(e.spells[0],false);renderHud();}
function startGame(nextMode=mode){runId++;mode=nextMode;phase='battle';round=0;p=freshPlayer();score=chain=totalCounters=totalSpells=elapsed=0;selectedRelics=[];runes=[];castCd=dodgeCd=dodgeTime=counterCd=wardTime=0;playerX=0;$('opening').classList.add('hidden');$('modal').close();$('battle-log').innerHTML='';$('relics').innerHTML='';$('nav-trial').classList.toggle('active',mode==='endless');$('nav-duel').classList.toggle('active',mode==='campaign');seedEnemy();renderRunes();announce('决斗开始','先用 Q Q Q 编织陨星之焰，再按空格释放',3);log('提示：火焰来袭时，按 T 再按 F 反制。',ELEMENTS.arcane.color);tone(480,.3,'triangle');}
function setIntent(element,casting){const el=ELEMENTS[element];$('intent-symbol').textContent=el.glyph;$('intent-symbol').style.color=el.color;$('intent-name').textContent=({fire:'余烬之息',ice:'寒霜穿刺',lightning:'惊雷之怒',earth:'崩岩重击',arcane:'虚空裂隙'})[element];$('intent-caption').textContent=casting?'咏唱中 · 准备克制符文':phase==='ready'?'开始后，观察对手的咏唱':'正在寻找破绽…';const weak=ELEMENTS[el.weak];$('counter-guide').innerHTML=`用 <span style="color:${weak.color}">${weak.name} ${weak.key}</span> 反制${el.name}`;$('intent-progress').style.background=el.color;}
function cast(){if(phase==='ready'){const prepared=[...runes];startGame();runes=prepared;renderRunes();if(!runes.length)return;}if(!active())return false;if(!runes.length){log('先选择至少一枚元素符文');return false;}if(castCd>0)return false;const spell=getSpell(runes),cost=Math.ceil(spell.cost*p.costMult);if(p.mana<cost){announce('魔力不足','等待回复，或用反制补充魔力',1.2);tone(130,.13);return false;}p.mana-=cost;runes=[];castCd=.65;totalSpells++;p.charge=clamp(p.charge+(6+spell.runes.length*2)*p.chargeRate,0,100);renderRunes();scene?.castAura(spell.element);tone(180+spell.runes.length*100,.3,'triangle');
const defensive=['fortress','heal','renew','wall','steam'].includes(spell.effect);if(defensive){let shield={fortress:45,heal:18,renew:25,wall:32,steam:12}[spell.effect]||0;let heal={fortress:16,heal:22,renew:32}[spell.effect]||0;p.shield=Math.min(90,p.shield+shield);p.hp=Math.min(p.maxHp,p.hp+heal);scene?.burst(playerX,4.2,ELEMENTS[spell.element].hex,25,.7);log(`${spell.name} · ${heal?'回复 '+heal+' 生命 · ':''}获得 ${shield} 护盾`,ELEMENTS.earth.color);}
if(spell.effect==='blink')dodgeCd=0;if(spell.effect==='leech')p.mana=clamp(p.mana+6,0,p.maxMana);
if(spell.damage){const visual=scene?.spawnProjectile('player',spell.element,spell.runes.length,.65);attacks.push({side:'player',time:.65,damage:spell.damage*p.power,spell,visual});log(`释放 ${spell.name}`,ELEMENTS[spell.element].color);}renderHud();return true;}
function hitEnemy(attack){if(!active())return;let damage=attack.damage;const effect=attack.spell?.effect||'none';if(effect==='detonate'&&enemyBurn>0){damage+=18*p.power;announce('引爆灼烧','爆燃新星造成额外伤害',1);}const pierce=effect==='pierce'||attack.reflected;let absorbed=0;if(e.shield>0&&!pierce){absorbed=Math.min(e.shield,damage);e.shield-=absorbed;damage-=absorbed;}if(e.ward&&!enemyCast&&enemyFreeze<=0&&!pierce){damage*=.7;log('虚空织法者的魔障抵消了部分伤害');}e.hp=Math.max(0,e.hp-damage);score+=Math.round(damage*2);scene?.burst(enemyX,-4.2,ELEMENTS[attack.spell?.element||'arcane'].hex,25,1);floatDamage(damage,true,damage<1?'护盾吸收':undefined);
if(effect==='burn'||effect==='chaos')enemyBurn=5;if(effect==='freeze'||effect==='chaos'){enemyFreeze=e.boss?1.2:attack.spell.runes.length===3?2.8:1.8;log('对手被冻结，咏唱暂时停滞',ELEMENTS.ice.color);}if(effect==='slow')enemySlow=5;if(effect==='interrupt'){enemyCast=null;enemyTimer=2.6;announce('咏唱打断','地磁脉冲打断了对手',1.2);}if(effect==='shock')scene?.lightning();if(e.boss&&!e.enraged&&e.hp<e.maxHp*.5){e.enraged=true;e.interval*=.78;e.cast*=.85;announce('星蚀降临','大秘法师进入第二阶段',2.3);log('首领第二阶段：咏唱速度提高。');}if(e.hp<=0)winRound();renderHud();}
function takeDamage(damage,element){if(!active())return;if(dodgeTime>0){score+=20;p.charge=clamp(p.charge+4,0,100);floatDamage(0,false,'闪避');log('残影闪避 · 来袭法术落空',ELEMENTS.ice.color);return;}if(wardTime>0){damage*=.4;wardTime=0;log('符文格挡减免了 60% 伤害');}const absorbed=Math.min(p.shield,damage);p.shield-=absorbed;damage-=absorbed;p.hp=Math.max(0,p.hp-damage);chain=0;scene?.burst(playerX,4.2,ELEMENTS[element].hex,22,.9);if(damage>0){floatDamage(damage,false);$('damage-flash').classList.add('hit');setTimeout(()=>$('damage-flash').classList.remove('hit'),250);tone(110,.3,'sawtooth',.035);}else floatDamage(0,false,'护盾吸收');log(`${ELEMENTS[element].name}命中 · ${Math.round(damage)} 伤害`);if(p.hp<=0)endRun(false);renderHud();}
function counter(){if(!active()||counterCd>0)return false;const incoming=attacks.filter(a=>a.side==='enemy').sort((a,b)=>a.time-b.time)[0];const telegraph=enemyCast&&enemyCast.remaining<.85+p.counterWindow?enemyCast:null;const target=incoming||telegraph;const rune=runes.at(-1);if(!rune){announce('需要反制符文','按提示选择克制元素，再按 F',1.3);return false;}counterCd=.7;const targetEl=target?.element;const correct=targetEl&&ELEMENTS[rune].counter===targetEl;const timing=incoming?incoming.time<=.7+p.counterWindow:!!telegraph;if(correct&&timing){const perfect=incoming?incoming.time<=p.counterWindow:enemyCast.remaining<=p.counterWindow;const damage=(target.damage||e.damage)*(perfect?2.5:1.8)*p.reflect;runes.pop();if(incoming){attacks=attacks.filter(a=>a!==incoming);scene?.removeProjectile(incoming.visual);}else{enemyCast=null;enemyTimer=e.interval;}p.mana=Math.min(p.maxMana,p.mana+(perfect?20:12));p.hp=Math.min(p.maxHp,p.hp+p.counterHeal);p.charge=clamp(p.charge+(perfect?22:15)*p.chargeRate,0,100);chain++;totalCounters++;score+=perfect?150+chain*20:80+chain*15;scene?.burst(playerX,4.2,ELEMENTS[rune].hex,32,1.2);const visual=scene?.spawnProjectile('player',rune,3,.48);attacks.push({side:'player',time:.48,damage,reflected:true,spell:{element:rune,effect:'pierce',runes:[rune]},visual});announce(perfect?'完美反制':'法术反制',`${ELEMENTS[targetEl].name}已反射 · ${chain} 连续反制`,1.8);tone(perfect?920:700,.4,'sine');log(`${perfect?'完美反制':'成功反制'} · 回复魔力 ${perfect?20:12}`,ELEMENTS[rune].color);renderRunes();renderHud();return true;}
wardTime=.8;runes.pop();renderRunes();scene?.burst(playerX,4.2,ELEMENTS[rune].hex,12,.5);if(targetEl&&!correct)announce('元素未克制','格挡开启 · 本次受到的伤害降低',1.1);else announce('符文格挡','等待法术接近时反制，可反射攻击',1);return false;}
function dodge(direction){if(!active()||dodgeCd>0)return false;dodgeCd=p.dodgeMax;dodgeTime=p.dodgeDuration;playerX=direction?clamp(playerX+direction*2,-3.5,3.5):playerX>=0?-2.8:2.8;scene?.burst(playerX,4.2,0x90b5dd,15,.6);tone(280,.2,'sine');return true;}
function ultimate(){if(!active()||p.charge<100)return false;p.charge=0;enemyCast=null;enemyTimer=3.6;for(const a of attacks.filter(a=>a.side==='enemy'))scene?.removeProjectile(a.visual);attacks=attacks.filter(a=>a.side==='player');p.hp=Math.min(p.maxHp,p.hp+20);p.mana=Math.min(p.maxMana,p.mana+30);scene?.ultimate();announce('奥 术 觉 醒','清除来袭法术 · 回复生命与魔力',2.5);hitEnemy({damage:85*p.power,reflected:true,spell:{effect:'pierce',element:'arcane',runes:['arcane','arcane','arcane']}});tone(1000,.8,'triangle',.12);renderHud();return true;}
function saveBest(){if(score>best){best=score;try{localStorage.setItem('runeweaver.best',String(best));}catch{}$('best-score').textContent=best.toLocaleString();}}
function winRound(){if(!active())return;phase='reward';score+=250+(round+1)*100+Math.round(p.hp);saveBest();attacks=[];enemyCast=null;scene?.clearProjectiles();announce('决斗胜利',`${e.name} 已被击败`,2);tone(680,.5,'sine');if(mode==='campaign'&&round===5){endRun(true);return;}const thisRun=runId;setTimeout(()=>{if(phase==='reward'&&thisRun===runId)showRewards();},1100);}
function showRewards(){const choices=[...RELICS].sort(()=>Math.random()-.5).slice(0,3);showModal(`<span class="modal-eyebrow">VICTORY · CHOOSE YOUR RELIC</span><h2>胜利属于织法者</h2><p class="subtitle">第 ${round+1} 场决斗完成。选择一件遗物，为下一场编织新的可能。<br>进入下一场时恢复 25 点生命，并补满魔力。</p><div class="reward-grid">${choices.map(r=>`<button class="reward-card" data-relic="${r.id}"><span>${r.icon}</span><b>${r.name}</b><p>${r.desc}</p></button>`).join('')}</div>`,false);$('modal-content').querySelectorAll('[data-relic]').forEach(btn=>btn.onclick=()=>{const r=RELICS.find(r=>r.id===btn.dataset.relic);r.apply(p);selectedRelics.push(r.id);p.hp=Math.min(p.maxHp,p.hp+25);p.mana=p.maxMana;p.shield=Math.min(90,p.shield+p.startShield);runes=[];round++;phase='battle';castCd=dodgeCd=counterCd=wardTime=0;dodgeTime=0;seedEnemy();renderRunes();$('modal').close();$('relics').innerHTML=selectedRelics.map(id=>{const r=RELICS.find(r=>r.id===id);return`<span class="relic-badge" title="${r.name}：${r.desc}">${r.icon}</span>`}).join('');announce(`第 ${round+1} 场决斗`,e.name,2);log(`获得 ${r.name}`, '#d6c092');});}
function endRun(won){phase=won?'victory':'defeat';saveBest();attacks=[];enemyCast=null;scene?.clearProjectiles();const thisRun=runId;setTimeout(()=>{if(thisRun!==runId)return;showModal(`<span class="modal-eyebrow">${won?'THE RUNES ANSWER YOUR CALL':'A NEW SPELL AWAITS'}</span><h2>${won?'星环之主 · 试炼完成':'你的符文尚未熄灭'}</h2><p class="subtitle">${won?'六位秘法对手已悉数败下阵来。你已掌握星环圣殿的秘密。':'这场决斗已经结束。观察敌方咏唱，使用克制元素反射法术，或在法术命中前闪避。'}</p><div class="result-stats"><div><strong>${score}</strong><span>秘法积分</span></div><div><strong>${totalCounters}</strong><span>成功反制</span></div><div><strong>${totalSpells}</strong><span>释放法术</span></div><div><strong>${round+(won?1:0)}</strong><span>击败对手</span></div></div><div class="modal-footer"><button class="gold-button" id="restart-game">再次挑战</button><button class="outline-button" id="continue-endless">${won?'进入无尽试炼':'查看符文之书'}</button></div>`,false);$('restart-game').onclick=()=>startGame(mode);$('continue-endless').onclick=()=>won?startGame('endless'):showBook();},800);}
function renderHud(){const hp=clamp(p.hp/p.maxHp*100,0,100),mana=clamp(p.mana/p.maxMana*100,0,100);$('player-health').style.width=hp+'%';$('player-hp').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}${p.shield>0?'  +'+Math.ceil(p.shield)+' 盾':''}`;$('mana-text').textContent=`${Math.floor(p.mana)} / ${p.maxMana}`;$('mana-bar').style.width=mana+'%';$('enemy-health').style.width=clamp((e.hp||0)/(e.maxHp||1)*100,0,100)+'%';$('enemy-hp').textContent=`${Math.ceil(e.hp||0)} / ${e.maxHp||120}${e.shield>0?'  +'+Math.ceil(e.shield)+' 盾':''}`;$('score').textContent=String(score).padStart(4,'0');$('combo-label').textContent=chain>1?`${chain} 连续反制 · 积分加成`:chain===1?'反制成功 · 保持专注':phase==='ready'?'编织你的第一道法术':`${totalSpells} 次施法 · ${totalCounters} 次反制`;$('ultimate-charge').textContent=p.charge>=100?'已就绪 · X':`${Math.floor(p.charge)}% · X`;$('ultimate-btn').classList.toggle('ready',p.charge>=100);$('dodge-cooldown').style.width=(1-clamp(dodgeCd/p.dodgeMax,0,1))*100+'%';$('dodge-btn').querySelector('kbd').textContent=dodgeCd>0?dodgeCd.toFixed(1)+' s':'Shift';$('cast-btn').style.opacity=castCd>0?'.65':'1';$('counter-btn').classList.toggle('active-counter',wardTime>0);$('enemy-status').textContent=enemyFreeze>0?'❄ 冻结 '+enemyFreeze.toFixed(1)+'s':enemyBurn>0?'♨ 灼烧':e.enraged?'星蚀形态':enemyCast?'正在咏唱':phase==='ready'?'等待决斗':'寻找破绽';$('player-rank').textContent=round<2?'初阶织法者':round<4?'秘法行者':'星环织法师';}
function showModal(content,closable=true){$('modal-content').innerHTML=content;$('modal-close').classList.toggle('hidden',!closable);if(!$('modal').open)$('modal').showModal();$('modal').dataset.closable=String(closable);}
function pauseForModal(){if(active()){resumePhase='battle';phase='paused';}else if(phase==='ready'){resumePhase='ready';}else resumePhase=phase;}
function closeModal(){if($('modal').dataset.closable==='false')return;$('modal').close();if(phase==='paused')phase=resumePhase||'battle';if(['defeat','victory'].includes(phase)){$('opening').classList.remove('hidden');$('opening').querySelector('h2').textContent='新的试炼，新的可能。';$('start-btn').textContent='重新挑战';}resumePhase=null;}
function showBook(){pauseForModal();showModal(`<span class="modal-eyebrow">THE GRIMOIRE</span><h2>符文之书</h2><p class="subtitle">五种元素，无限织法。组合顺序不影响配方；额外重复一枚元素可强化双元素法术。<br>点击任意配方即可装入符文槽。单元素也能直接施法。</p><div class="book-grid">${SPELLS.map((s,i)=>`<button class="book-spell" data-spell="${i}" style="--rune-color:${ELEMENTS[s.runes[0]].color}"><span>${s.runes.map(r=>ELEMENTS[r].glyph).join(' ')}</span><b>${s.name}</b><p>${s.desc}</p><small>${s.runes.map(r=>ELEMENTS[r].key).join(' + ')} · ${Math.ceil(s.cost*p.costMult)} 魔力</small></button>`).join('')}</div>`);$('modal-content').querySelectorAll('[data-spell]').forEach(btn=>btn.onclick=()=>{if(['reward','victory','defeat'].includes(phase)){log('开始新决斗后即可使用配方');return;}runes=[...SPELLS[+btn.dataset.spell].runes];renderRunes();closeModal();});}
function showHelp(){pauseForModal();showModal(`<span class="modal-eyebrow">THE ART OF RUNEWEAVING</span><h2>每一道咏唱，都有破绽。</h2><p class="subtitle">在六场 3D 决斗中掌握元素，选择遗物，挑战星蚀大秘法师。</p><div class="guide-grid"><div class="guide-card"><h3>01 · 编织与释放</h3><p>Q 火焰 · W 寒冰 · E 雷电 · R 大地 · T 奥术。<br>装入最多 3 枚符文，按 Space 或点击「释放法术」。点击画布也能施法。Backspace 撤销末枚符文。</p></div><div class="guide-card"><h3>02 · 克制与反制</h3><p>火克冰、冰克土、土克雷、雷克奥、奥克火。<br>选择克制元素作为最后一枚符文，在敌方咏唱接近结束或法术飞来时按 F / 右键。越接近命中，反制收益越高。错误元素只能格挡。</p></div><div class="guide-card"><h3>03 · 闪避与觉醒</h3><p>A / D 左右移动；Shift 或点击「闪避」获得短暂无敌。<br>施法与反制积累觉醒能量，满额时按 X 清除来袭法术、恢复生命并轰击对手。</p></div><div class="guide-card"><h3>04 · 手势施法</h3><p>在竞技场空白处按住鼠标或用手指拖动。↑ 火焰，↓ 寒冰，→ 或 ← 大地，Z 形雷电，圆形奥术。每次手势装入一枚符文。</p></div></div><div class="gesture-row">${Object.values(ELEMENTS).map(e=>`<div class="gesture-item" style="color:${e.color}"><strong>${e.gesture}</strong>${e.name} · ${e.key}</div>`).join('')}</div><p class="subtitle">魔力会持续恢复；受击优先消耗护盾。每次胜利后恢复生命、补满魔力，并选择一件永久生效至本轮结束的遗物。切换页面时游戏自动暂停。</p>`);}
function pause(){if(active()){pauseForModal();showModal(`<span class="modal-eyebrow">A MOMENT BETWEEN SPELLS</span><h2>时间已静止</h2><p class="subtitle">你正在第 ${round+1} 场决斗。深呼吸，再编织下一道法术。</p><div class="modal-footer"><button class="gold-button" id="resume-game">继续决斗</button><button class="outline-button" id="restart-pause">重新开始</button></div>`);$('resume-game').onclick=closeModal;$('restart-pause').onclick=()=>startGame(mode);}else if(phase==='paused'&&$('modal').open)closeModal();}
$('element-cards').innerHTML=Object.entries(ELEMENTS).map(([id,e])=>`<button class="element-card" data-element="${id}" style="--element-color:${e.color}" aria-label="添加${e.name}符文，快捷键 ${e.key}"><kbd>${e.key}</kbd><span class="gesture-mini">${e.gesture}</span><strong>${e.glyph}</strong><span>${e.name}</span></button>`).join('');document.querySelectorAll('[data-element]').forEach(b=>b.onclick=()=>addRune(b.dataset.element));document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{if(['battle','ready'].includes(phase)){runes=b.dataset.recipe.split(',');renderRunes();tone(420,.15);}});
$('start-btn').onclick=()=>startGame(mode);$('cast-btn').onclick=cast;$('counter-btn').onclick=counter;$('dodge-btn').onclick=()=>dodge();$('ultimate-btn').onclick=ultimate;$('clear-btn').onclick=()=>{runes=[];renderRunes();};$('help-btn').onclick=showHelp;$('gesture-help').onclick=showHelp;$('nav-book').onclick=showBook;$('all-spells').onclick=showBook;$('pause-btn').onclick=pause;$('modal-close').onclick=closeModal;$('nav-duel').onclick=()=>{if(mode==='campaign')return;if(phase==='ready'){mode='campaign';$('nav-trial').classList.remove('active');$('nav-duel').classList.add('active');}else showModePrompt('campaign');};$('nav-trial').onclick=()=>showModePrompt('endless');
function showModePrompt(next){pauseForModal();showModal(`<span class="modal-eyebrow">${next==='endless'?'ENDLESS ASCENSION':'THE SIXFOLD TRIAL'}</span><h2>${next==='endless'?'无尽试炼':'六重试炼'}</h2><p class="subtitle">${next==='endless'?'突破六场决斗的界限。敌人将轮番回归，每轮获得更高生命与伤害，遗物可持续叠加。':'挑战六位独特对手，在最后一战直面拥有双阶段的星蚀大秘法师。'}<br>开始后会重置当前进度，最高纪录将被保留。</p><div class="modal-footer"><button class="gold-button" id="confirm-mode">开始${next==='endless'?'无尽试炼':'六重试炼'}</button><button class="outline-button" id="cancel-mode">返回</button></div>`);$('confirm-mode').onclick=()=>startGame(next);$('cancel-mode').onclick=closeModal;}
$('sound-btn').onclick=()=>{sound=!sound;$('sound-btn').textContent=sound?'♫':'♪';$('sound-btn').title=sound?'关闭声音':'开启声音';$('sound-btn').setAttribute('aria-label',sound?'关闭声音':'开启声音');$('sound-btn').style.color=sound?'var(--gold)':'';tone(600,.2);};
$('modal').addEventListener('cancel',ev=>{ev.preventDefault();closeModal();});$('modal').addEventListener('click',ev=>{if(ev.target===$('modal')){const r=$('modal').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal();}});
const held=new Set();document.addEventListener('keydown',ev=>{if(ev.target instanceof HTMLInputElement)return;const key=ev.key.toLowerCase();if([' ','backspace','shift','arrowleft','arrowright'].includes(key))ev.preventDefault();if(ev.repeat)return;if(key==='escape'){if($('modal').open)closeModal();else pause();return;}if($('modal').open)return;held.add(key);const element=Object.keys(ELEMENTS).find(e=>ELEMENTS[e].key.toLowerCase()===key);if(element){addRune(element);return;}if(key==='enter'&&phase==='ready')startGame();else if(key===' ')cast();else if(key==='f')counter();else if(key==='shift')dodge(held.has('a')?-1:held.has('d')?1:undefined);else if(key==='x')ultimate();else if(key==='backspace'){runes.pop();renderRunes();}else if(key==='g')showBook();});document.addEventListener('keyup',ev=>held.delete(ev.key.toLowerCase()));window.addEventListener('blur',()=>{held.clear();if(active())pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active()){wasHidden=true;pause();}});
const gestureCanvas=$('gesture-canvas'),gctx=gestureCanvas.getContext('2d');let drawing=false,points=[],gesturePointer=null;function sizeGesture(){gestureCanvas.width=$('arena').clientWidth;gestureCanvas.height=$('arena').clientHeight;}new ResizeObserver(sizeGesture).observe($('arena'));const arena=$('arena');arena.addEventListener('contextmenu',ev=>{ev.preventDefault();counter();});arena.addEventListener('pointerdown',ev=>{if(ev.button!==0||ev.target.closest('button,a,aside,.battle-top,.opening,.weave-area')||!['ready','battle'].includes(phase)||$('modal').open)return;drawing=true;gesturePointer=ev.pointerId;points=[];arena.setPointerCapture(ev.pointerId);const r=arena.getBoundingClientRect();points.push({x:ev.clientX-r.left,y:ev.clientY-r.top});});arena.addEventListener('pointermove',ev=>{if(!drawing||ev.pointerId!==gesturePointer)return;const r=arena.getBoundingClientRect();const point={x:ev.clientX-r.left,y:ev.clientY-r.top};if(Math.hypot(point.x-points.at(-1).x,point.y-points.at(-1).y)<3)return;points.push(point);gctx.clearRect(0,0,gestureCanvas.width,gestureCanvas.height);gctx.beginPath();gctx.moveTo(points[0].x,points[0].y);for(const p of points)gctx.lineTo(p.x,p.y);gctx.strokeStyle='#d0bcff';gctx.lineWidth=2;gctx.lineCap='round';gctx.shadowColor='#ab83ef';gctx.shadowBlur=14;gctx.stroke();});function finishGesture(ev){if(!drawing||ev.pointerId!==gesturePointer)return;drawing=false;const bounds=arena.getBoundingClientRect();points.push({x:ev.clientX-bounds.left,y:ev.clientY-bounds.top});const travel=points.slice(1).reduce((n,p,i)=>n+Math.hypot(p.x-points[i].x,p.y-points[i].y),0);const el=recognizeGesture(points);if(el){addRune(el);log(`手势识别 · ${ELEMENTS[el].name}`,ELEMENTS[el].color);}else if(travel<12&&active())cast();else if(travel>=12)log('手势太短 · 请画出完整轨迹');setTimeout(()=>{if(!drawing)gctx.clearRect(0,0,gestureCanvas.width,gestureCanvas.height);},170);}arena.addEventListener('pointerup',finishGesture);arena.addEventListener('pointercancel',()=>{drawing=false;points=[];gctx.clearRect(0,0,gestureCanvas.width,gestureCanvas.height);});$('scene').style.touchAction='none';
function update(dt){if(announceTime>0){announceTime-=dt;if(announceTime<=0)$('announcement').innerHTML='';}if(!active())return;elapsed+=dt;castCd=Math.max(0,castCd-dt);dodgeCd=Math.max(0,dodgeCd-dt);dodgeTime=Math.max(0,dodgeTime-dt);counterCd=Math.max(0,counterCd-dt);wardTime=Math.max(0,wardTime-dt);p.mana=Math.min(p.maxMana,p.mana+dt*p.regen);enemyFreeze=Math.max(0,enemyFreeze-dt);enemySlow=Math.max(0,enemySlow-dt);if(held.has('a')||held.has('arrowleft'))playerX=clamp(playerX-dt*4,-3.5,3.5);if(held.has('d')||held.has('arrowright'))playerX=clamp(playerX+dt*4,-3.5,3.5);if(round>=2&&!enemyCast&&enemyFreeze<=0)enemyX=Math.sin(elapsed*.55)*2.1;
if(enemyBurn>0){enemyBurn-=dt;burnTick+=dt;if(burnTick>=1){burnTick=0;e.hp=Math.max(0,e.hp-4*p.power);score+=8;floatDamage(4*p.power,true);if(e.hp<=0){winRound();return;}}}else burnTick=0;
for(const a of [...attacks]){if(!attacks.includes(a))continue;a.time-=dt;if(a.time<=0){attacks=attacks.filter(x=>x!==a);if(a.side==='player')hitEnemy(a);else{const missed=Math.abs(playerX-a.targetX)>1.3;if(missed){score+=15;floatDamage(0,false,'避开');log('移动避开了来袭法术');}else takeDamage(a.damage,a.element);}if(!active())return;}}
if(enemyFreeze<=0){const speed=enemySlow>0?.5:1;if(enemyCast){enemyCast.remaining-=dt*speed;$('intent-progress').style.width=(1-enemyCast.remaining/enemyCast.total)*100+'%';$('intent-caption').textContent=`咏唱中 · ${Math.max(0,enemyCast.remaining).toFixed(1)} 秒`;
if(enemyCast.remaining<=0){const element=enemyCast.element,damage=e.damage,visual=scene?.spawnProjectile('enemy',element,2,1.15);attacks.push({side:'enemy',element,time:1.15,damage,visual,targetX:playerX});enemyCast=null;enemyTimer=e.interval;$('intent-progress').style.width='100%';$('intent-caption').textContent='法术来袭 · 现在反制！';tone(220,.25,'sawtooth',.025);}}
else{enemyTimer-=dt*speed;if(enemyTimer<=0){const element=e.spells[attackIndex++%e.spells.length];enemyCast={element,remaining:e.cast,total:e.cast,damage:e.damage};setIntent(element,true);scene?.castAura(element,true);}else if(!attacks.some(a=>a.side==='enemy')){$('intent-progress').style.width='0%';$('intent-caption').textContent='正在寻找破绽…';}}}else $('intent-caption').textContent=`被冻结 · ${enemyFreeze.toFixed(1)} 秒`;renderHud();}
let previous=performance.now(),hudTime=0;function loop(now){const dt=Math.min(.05,(now-previous)/1000);previous=now;update(dt);if(scene){scene.update(phase==='paused'||$('modal').open?0:dt,{playerX,enemyX,shield:p.shield,enemyShield:e.shield||0,dodging:dodgeTime>0,casting:!!enemyCast});const pos=scene.projectPosition(enemyX,3.8,-4.2);$('world-label').style.left=pos.x+'px';$('world-label').style.top=pos.y+'px';}requestAnimationFrame(loop);}seedEnemy();renderRunes();requestAnimationFrame(loop);
// A structured, optional interface mirrors the exact visible game actions.
const readState=()=>({phase,mode,round:round+1,score,player:{hp:p.hp,mana:p.mana,shield:p.shield,charge:p.charge},enemy:{name:e.name,hp:e.hp,element:enemyCast?.element,castRemaining:enemyCast?.remaining},runes:[...runes],relics:[...selectedRelics],incoming:attacks.filter(a=>a.side==='enemy').map(a=>({element:a.element,time:a.time}))});
window.runeweaver={getState:readState,start:startGame,addRune,cast,counter,dodge,ultimate,pause};
if(document.modelContext?.registerTool){const controller=new AbortController();const tools=[{name:'read_duel_state',description:'Read the current rune duel, selected runes, enemy casting, and player resources.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>readState()},{name:'compose_rune_spell',description:'Replace the visible rune queue with one to three selected elements. Does not cast the spell.',inputSchema:{type:'object',properties:{elements:{type:'array',items:{type:'string',enum:Object.keys(ELEMENTS)},minItems:1,maxItems:3}},required:['elements'],additionalProperties:false},execute:input=>{if(!Array.isArray(input.elements)||input.elements.length<1||input.elements.length>3||input.elements.some(e=>!ELEMENTS[e]))throw Error('Choose one to three valid elements.');if(!['ready','battle'].includes(phase)||$('modal').open)throw Error('The duel is not accepting runes.');runes=[...input.elements];renderRunes();return{runes:[...runes],spell:getSpell(runes).name};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
